p='/home/USER/continual-arc-baselines/.workbench/stage1/H-hermes-luna6-medium-fresh0/frozen/held-out-reference/play/users/u013/system/state/hermes/state.db'; sid='f1038701-6437-4997-9ea0-2b53484f1420'
c=sqlite3.connect(p); c.row_factory=sqlite3.Row
rows=c.execute('select id,role,content,tool_name,tool_calls from messages where session_id=? and active=1 order by id',(sid,)).fetchall()
def parse_grids(txt):
 out=[]
 # parse each segment after input/output header through successive lines rows digits
 for m in re.finditer(r'(Demo pair \d+ (?:input|output) \(\d+x\d+\):)\n((?:[0-9 ]+\n?)+)',txt):
  label=m.group(1); block=m.group(2).strip().splitlines(); g=[[int(x) for x in line.split()] for line in block]
  out.append((label,g))
 return out
for row in rows:
 if row['role']=='user' and row['content'] and 'Demos received' in row['content']:
  print('\nUSER MSG',row['id'])
  for label,g in parse_grids(row['content']):
   coords=[(r,col,v) for r,line in enumerate(g) for col,v in enumerate(line) if v]
   print(label,'dims',len(g),len(g[0]),'nonzero',coords)
 if row['role']=='assistant':
  content=row['content'] or ''
  if '"action":"submit"' in content or '"action": "submit"' in content:
