    print('\nSUBMIT',row['id'], 'grid:',a.get('grid'))
   except Exception: print('SUBMIT RAW',row['id'],content[:1000])
  tc=row['tool_calls'] or ''
  if '"action":"submit"' in tc or '"action": "submit"' in tc:
   print('\nTOOL SUBMIT CALL',row['id'],tc[:2000])

