import sqlite3,re
p='/home/USER/continual-arc-baselines/.workbench/stage1/H-hermes-luna6-medium-fresh0/frozen/held-out-reference/play/users/u013/system/state/hermes/state.db'; c=sqlite3.connect(f'file:{p}?mode=ro',uri=True); sid='f1038701-6437-4997-9ea0-2b53484f1420'
msgs=[x[0] for x in c.execute("select content from messages where session_id=? and role='user' and active=1",(sid,)) if x[0]]
pairs=[]
for txt in msgs:
 for m in re.finditer(r'Demo pair (\d+) input \((\d+)x(\d+)\):\n(.*?)\nDemo pair \1 output \(\2x\3\):\n(.*?)(?=\n\nSame instance|\nWrong attempts|\Z)',txt,re.S):
  d=int(m.group(2)); parse=lambda s:[list(map(int,line.split())) for line in s.strip().splitlines()]
  pairs.append((int(m.group(1)),parse(m.group(4)),parse(m.group(5))))
print('pairs',[(i,len(a),len(b)) for i,a,b in pairs])
def solve(inp):
 n=len(inp); objects=[]
 for r in range(n):
  for col in range(n):
   if inp[r][col]==3: continue
   neigh=[(r-1,col),(r+1,col),(r,col-1),(r,col+1)]
   if all(0<=i<n and 0<=j<n and inp[i][j]==3 for i,j in neigh):
    objects.append(((r,col),inp[r][col],set(neigh)))
 marks=set()
 for _,_,arms in objects: marks |= arms
 # rays; own 3 arms transparent, other motif's 3 markers stop
 h=[];v=[]
 for (r,col),value,own in objects:
  if not value: continue
  for dr,dc,layer in [(0,-1,h),(0,1,h),(-1,0,v),(1,0,v)]:
   i,j=r+dr,col+dc
   while 0<=i<n and 0<=j<n:
    if inp[i][j]==3 and (i,j) not in own: break
    layer.append((i,j,value));i+=dr;j+=dc
 out=[row[:] for row in inp]
 for layer in (h,v):
  for i,j,value in layer:
   if out[i][j]!=3:out[i][j]=value
 return out,objects
for k,a,b in pairs:
 pred,objs=solve(a)
 dif=[(r,c,pred[r][c],b[r][c]) for r in range(len(a)) for c in range(len(a)) if pred[r][c]!=b[r][c]]
 print('demo',k,'objects',[(coord,val) for coord,val,_ in objs],'diff count',len(dif),'first',dif[:12])

